#include "CoordinateAxes.h"
#include <cassert>
#include <iostream>
using namespace CoordinateAxes;
int main(){std::vector<Segment> a={{Point(150,0),Point(150,200)},{Point(150,0),Point(154,8)},{Point(150,0),Point(146,8)},{Point(0,100),Point(300,100)},{Point(300,100),Point(292,104)},{Point(300,100),Point(292,96)}};Geometry g;assert(GeometryFromAxes(a,g));assert(g.form==9&&g.origin.x==150&&g.origin.y==100&&g.v.y==-1);assert(g.xmin==-150&&g.xmax==150&&g.ymin==-100&&g.ymax==100);for(auto &s:a){auto rotate=[](Point p){return Point(p.x*.866025403784-p.y*.5+42,p.x*.5+p.y*.866025403784-70);};s.a=rotate(s.a);s.b=rotate(s.b);}assert(GeometryFromAxes(a,g));assert(std::fabs(Length(g.u)-1)<1e-8&&std::fabs(Length(g.v)-1)<1e-8);double n;assert(ReadStep("pi/2",n)&&std::fabs(n-pi/2)<1e-12);assert(ReadStep("1/3",n)&&std::fabs(n-1./3)<1e-12);assert(ReadStep("1e-3",n)&&n==.001);for(auto t:{"0","-1","x+1","1/0","sqrt(-1)","oops"})assert(!ReadStep(t,n));long long num,den;assert(Rational(-3*pi/2/pi,num,den)&&num==-3&&den==2);assert(Rational(1./3,num,den)&&num==1&&den==3);assert(!Rational(std::sqrt(2.),num,den));Settings c;std::string error;assert(Valid(c,error));c.minorDarkness=0;assert(Ink(c,false)==0xffffff);c.minorDarkness=100;assert(Ink(c,false)==0);c.majorDarkness=30;c.color=1;assert(Ink(c,false)!=Ink(c,true));std::vector<int> ticks;assert(Ticks(-100,100,40,ticks)&&ticks==std::vector<int>({-2,-1,0,1,2}));assert(!Ticks(0,10000,1,ticks));assert(Number(-.0001,2)=="0.00");assert(Number(1.2,3)=="1.200");assert(Rational(1000000000.5,num,den)&&num==2000000001LL&&den==2);assert(!Rational(1e-12,num,den));assert(Number(.1+.2)=="0.3");auto dashed=Styled(Segment(Point(0,0),Point(21,0)),1);assert(dashed.size()==3&&dashed[0].b.x==6&&dashed[1].a.x==10&&dashed.back().b.x==21);c.role=1;auto h=Checksum(c);c.xName=L"\u03b8";assert(h!=Checksum(c));std::cout<<"Coordinate model passed: centered/rotated geometry, positive numeric/trig steps, exact fractions, contrast, bounded ticks, clean rounding and dashed endpoints.\n";}
